    // Invalidate JunctionCache for affected junction tables

    JunctionTableOps::JunctionCache::instance().invalidateTable(ROOT_SYSTEM_JUNCTION_TABLE);
    JunctionTableOps::JunctionCache::instance().invalidateTable(ROOT_WORKS_JUNCTION_TABLE);
